"use strict";(globalThis.webpackChunkgrc||=[]).push([[21054],{76180(e){e.exports=JSON.parse('{"citeKey":"he2017heterogeneityaware","slug":"he-2017-heterogeneity-aware-78c7","title":"Heterogeneity-Aware Collective I/O for Parallel I/O Systems with Hybrid HDD/SSD Servers","authors":["S. He","Y. Wang","X.-H. Sun","C. Huang","C. Xu"],"venue":"IEEE Transactions on Computers (TC), vol. 66, no. 6, pp. 1091-1098","type":"Journal","entryType":"article","date":"June, 2017","year":2017,"era":"iit","month":6,"doi":"10.1109/tc.2016.2637353","abstract":"Collective I/O is a widely used middleware technique that exploits I/O access correlation among multiple processes to improve I/O system performance. However, most existing implementations of collective I/O strategies are designed and optimized for homogeneous I/O systems. In practice, the homogeneity assumptions do not hold in heterogeneous parallel I/O systems, which consist of multiple HDD and SSD-based servers and become increasingly promising. In this paper, we propose a heterogeneity-aware collective-I/O (HACIO) strategy to enhance the performance of conventional collective I/O operations. HACIO reorganizes the order of I/O requests for each aggregator with awareness of the storage performance of heterogeneous servers, so that the hardware of the systems can be better utilized. We have implemented HACIO in ROMIO, a widely used MPI-IO library. Experimental results show that HACIO can significantly increase the I/O throughputs of heterogeneous I/O systems.","hasAbstract":true,"lede":"We propose a heterogeneity-aware collective-I/O (HACIO) strategy to enhance the performance of conventional collective I/O operations.","links":{"pdf":"https://grc.iit.edu/papers/2017/he-2017-heterogeneity-aware-78c7.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);